    snapshot_capture_failed = False
    llm_error_fallback_message: str | None = None
    pre_existing_message_ids: set[str] = set()
    journal = None
    try:
        if event_store is not None:
            journal = RunJournal(
                run_id=run_id,
                thread_id=thread_id,
                event_store=event_store,
