    )
    summary_model = FakeToolCallingModel(responses=[AIMessage(content="compressed summary")])
    agent = create_agent(
        model=model,
        tools=[fake_task],
        middleware=[
            DurableContextMiddleware(),
            DeerFlowSummarizationMiddleware(
                model=summary_model,
                trigger=("messages", 4),
                keep=("messages", 2),
                token_counter=len,
            ),
        ],
        state_schema=ThreadState,
        checkpointer=InMemorySaver(),
    )
